/**
 * @summary Remove an item from the account cart
 */
export const removeAccountCartItem = (
  itemId: string,
  mutateCartDto: BodyType<MutateCartDto>,
  options?: SecondParameter<typeof apiFetcher>,
) => {
  return apiFetcher<CartDto>(
    {
      url: `/api/v1/account/cart/items/${itemId}`,
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      data: mutateCartDto,
    },
    options,
  );
};

